import{at as e,it as t,t as n,vt as r}from"./chunks/framework.DkAysg6d.js";var i=JSON.parse(`{"title":"Filesystem tree","description":"","frontmatter":{},"headers":[],"relativePath":"showcase-tree.md","filePath":"pages/showcase-tree.md"}`),a={name:`showcase-tree.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="filesystem-tree" tabindex="-1">Filesystem tree <a class="header-anchor" href="#filesystem-tree" aria-label="Permalink to “Filesystem tree”">​</a></h1><p>A five-level tree over six volumes, six hundred and thirty-six directories, and fifty thousand files, virtualized while it is expanded.</p><p><a href="./demo/tree" target="_blank" rel="noreferrer">Open the route full screen</a></p><h2 id="what-it-is-stressing" tabindex="-1">What it is stressing <a class="header-anchor" href="#what-it-is-stressing" aria-label="Permalink to “What it is stressing”">​</a></h2><p>Tree flattening and virtualization at the same time. Expanding everything makes the flat list far longer than the document can hold, so the two stages have to agree on what index means at every scroll position.</p><h2 id="why-the-two-are-hard-together" tabindex="-1">Why the two are hard together <a class="header-anchor" href="#why-the-two-are-hard-together" aria-label="Permalink to “Why the two are hard together”">​</a></h2><p><code>flattenAxis</code> in <code>src/1_axis.ts</code> skips a closed node&#39;s whole subtree, so the visible list changes length on every toggle. The window is computed over that list through a sizer built on the page run, which means an expansion invalidates the offsets of every row after it.</p><p>The expand-all control is the sharpest case: one write, and the flat list grows by two orders of magnitude while the rendered element count stays where it was.</p><h2 id="features-it-exercises" tabindex="-1">Features it exercises <a class="header-anchor" href="#features-it-exercises" aria-label="Permalink to “Features it exercises”">​</a></h2><p>Tree data, expansion, sort, per-row height, row virtualization, scroll position, density, and slots.</p><h2 id="what-to-watch-in-the-readout" tabindex="-1">What to watch in the readout <a class="header-anchor" href="#what-to-watch-in-the-readout" aria-label="Permalink to “What to watch in the readout”">​</a></h2><table tabindex="0"><thead><tr><th>number</th><th>what it tells you</th></tr></thead><tbody><tr><td>the relation sizes</td><td>how many nodes the forest holds</td></tr><tr><td>the flat list length</td><td>how many are visible after expansion</td></tr><tr><td>the plan&#39;s center run</td><td>how many are candidates after pinning and paging</td></tr><tr><td>the DOM element count</td><td>how many actually exist</td></tr></tbody></table><p>The gap between the third and the fourth is the whole point of the window.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related pages”">​</a></h2><p><a href="/hafley-rxjs/signal-grid/rows-tree">Tree data</a> and <a href="/hafley-rxjs/signal-grid/view-virtualize">Virtualization</a> cover the two halves at page scale, each with a panel you can edit.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};